-- Estudiantes que aprobaron las materias -- aprobados_materias
--
-- Decide quien va a SIIS (Cambio 90): solo se informan los casos cuyo DNI figure
-- aca. Si la tabla no existe, procesar_casos_siis y la pantalla del proceso
-- masivo se niegan a correr, a proposito.
--
-- El DNI va como texto: hay al menos uno que no es un numero ('B 03746926') y
-- con INT la carga entera se cae en esa fila. El cruce normaliza los ceros a la
-- izquierda, asi que da lo mismo como este cargado.
--
-- Se ejecuta contra la base, no desde el pod (la imagen no trae cliente):
--   mariadb -h <host> -u <usuario> -p <base> < scripts/Aprobados.sql

SET NAMES utf8mb4;

DROP TABLE IF EXISTS `aprobados_materias`;

CREATE TABLE `aprobados_materias` (
    `dni` VARCHAR(20) NOT NULL COMMENT 'DNI del estudiante que aprobo las materias',
    KEY `idx_dni` (`dni`)
);


-- Verificacion: tiene que devolver la cantidad de DNI cargados.
SELECT COUNT(*) AS dni_habilitados FROM `aprobados_materias`;
